-- 444: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 2 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_444_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_444_guard;
INSERT INTO _migration_444_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_006' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The roots of 2x² − 3x − 5 = 0 are α and β. Find the value of 1/α + 1/β.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 3/5","B. −5/3","C. −3/10","D. −3/5"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The sum of the roots is α + β = −(−3)/2 = 3/2 and the product is αβ = −5/2. Then 1/α + 1/β = (α + β)/(αβ) = (3/2) ÷ (−5/2) = (3/2) × (−2/5) = −3/5. Therefore the correct answer is D: −3/5.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_006' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_444_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_007' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation x² + 4x − 5 = 0 by completing the square.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'x = 1 or x = −5' AND q.explanation IS 'Complete the square: x² + 4x − 5 = (x + 2)² − 4 − 5 = (x + 2)² − 9 = 0. So (x + 2)² = 9, giving x + 2 = ±3. Hence x = 3 − 2 = 1 or x = −3 − 2 = −5. Check by factorising: (x − 1)(x + 5) = 0 gives the same roots. Answer: x = 1 or x = −5.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_007' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_444_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_008' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the set of values of k for which the equation x² + 4x + k = 0 has real roots.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'k ≤ 4' AND q.explanation IS 'Real roots require the discriminant to be non-negative: b² − 4ac ≥ 0. Here a = 1 and b = 4, so 4² − 4(1)(k) ≥ 0, giving 16 − 4k ≥ 0, hence 4k ≤ 16 and k ≤ 4. Answer: k ≤ 4.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_008' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_444_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_009' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The angles of a triangle are x°, 2x° and 3x°. Find the size of the largest angle.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 90°","B. 30°","C. 60°","D. 120°"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The angles of a triangle sum to 180°: x + 2x + 3x = 6x = 180, so x = 30. The largest angle is 3x = 3 × 30 = 90°. (30° is only the smallest angle.) Therefore the correct answer is A: 90°.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_009' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_444_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_010' AND NOT (q.topic_id IS 'topic_wcoremath_geometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Each interior angle of a regular polygon is 156°. How many sides does the polygon have?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 12","B. 15","C. 18","D. 20"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Each exterior angle is 180° − 156° = 24°. The exterior angles of any polygon sum to 360°, so the number of sides is 360 ÷ 24 = 15. Therefore the correct answer is B: 15.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_010' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_006', 'topic_wcoremath_quadratic', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The roots of 2x² − 3x − 5 = 0 are α and β. Find the value of 1/α + 1/β.', 'multiple_choice', NULL, '["A. 3/5","B. −5/3","C. −3/10","D. −3/5"]', 'D', 'The sum of the roots is α + β = −(−3)/2 = 3/2 and the product is αβ = −5/2. Then 1/α + 1/β = (α + β)/(αβ) = (3/2) ÷ (−5/2) = (3/2) × (−2/5) = −3/5. Therefore the correct answer is D: −3/5.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_007', 'topic_wcoremath_quadratic', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation x² + 4x − 5 = 0 by completing the square.', 'calculation', NULL, NULL, 'x = 1 or x = −5', 'Complete the square: x² + 4x − 5 = (x + 2)² − 4 − 5 = (x + 2)² − 9 = 0. So (x + 2)² = 9, giving x + 2 = ±3. Hence x = 3 − 2 = 1 or x = −3 − 2 = −5. Check by factorising: (x − 1)(x + 5) = 0 gives the same roots. Answer: x = 1 or x = −5.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_008', 'topic_wcoremath_quadratic', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the set of values of k for which the equation x² + 4x + k = 0 has real roots.', 'calculation', NULL, NULL, 'k ≤ 4', 'Real roots require the discriminant to be non-negative: b² − 4ac ≥ 0. Here a = 1 and b = 4, so 4² − 4(1)(k) ≥ 0, giving 16 − 4k ≥ 0, hence 4k ≤ 16 and k ≤ 4. Answer: k ≤ 4.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_009', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The angles of a triangle are x°, 2x° and 3x°. Find the size of the largest angle.', 'multiple_choice', NULL, '["A. 90°","B. 30°","C. 60°","D. 120°"]', 'A', 'The angles of a triangle sum to 180°: x + 2x + 3x = 6x = 180, so x = 30. The largest angle is 3x = 3 × 30 = 90°. (30° is only the smallest angle.) Therefore the correct answer is A: 90°.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_010', 'topic_wcoremath_geometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Each interior angle of a regular polygon is 156°. How many sides does the polygon have?', 'multiple_choice', NULL, '["A. 12","B. 15","C. 18","D. 20"]', 'B', 'Each exterior angle is 180° − 156° = 24°. The exterior angles of any polygon sum to 360°, so the number of sides is 360 ÷ 24 = 15. Therefore the correct answer is B: 15.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-core-math-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_coremath_s2_006', 'q_was_coremath_s2_007', 'q_was_coremath_s2_008', 'q_was_coremath_s2_009', 'q_was_coremath_s2_010');
